// Generate a filename. FUZZ_PARAM_FILENAME() guarantees the file exists, though
// it may not be a valid WAVE. The function under test should handle failures.
const char *path = FUZZ_PARAM_FILENAME();
// Invoke target function
sherpa_onnx::cxx::Wave w = sherpa_onnx::cxx::ReadWave(path);
// Heap-allocate an output object so the fuzzer runtime can take ownership
sherpa_onnx::cxx::Wave *wave = new sherpa_onnx::cxx::Wave(std::move(w));
// Validation: We don't assert success since the file may be non-WAVE; returning
// the (possibly empty) Wave object is acceptable and useful for downstream stages.

// Enforce constraints on input wave; if invalid, bail early.
if (wave->sample_rate <= 0) { FUZZ_BAIL(); }
// Create a sanitized copy to satisfy normalized sample constraint [-1, 1].
sherpa_onnx::cxx::Wave wave_copy;
wave_copy.sample_rate = wave->sample_rate;
wave_copy.samples = wave->samples;
for (float &v : wave_copy.samples) {
  if (v > 1.0f) v = 1.0f;
  if (v < -1.0f) v = -1.0f;
}
// Choose a filename in a writable location.
const char *path = FUZZ_PARAM_FILENAME();
// Call the target function with the sanitized copy.
bool ok = sherpa_onnx::cxx::WriteWave(path, wave_copy);
// Per API, we must check the return value; bail on failure to prune invalid states.
if (!ok) { FUZZ_BAIL(); }
// Validation: Input object is preserved (returned as output); file path generated
// by runtime should be writable; we clamp samples and verify sample_rate > 0.

// Do not allow feeding after InputFinished was called on this stream.
if (FUZZ_GET_ATTR_INT(stream, "finished")) { FUZZ_BAIL(); }
// Generate a short random chunk of samples (0..512).
unsigned int r = *FUZZ_PARAM(unsigned int);
int32_t n = static_cast<int32_t>(r % 513);
// Pre-generate a fixed-size buffer; choose n slices from it.
const float (*buf)[512] = FUZZ_PARAM(float[512]);
const float *samples = (n > 0 ? &(*buf)[0] : nullptr);
// Constrain sample values to [-1, 1] on-the-fly by copying when needed.
std::vector<float> clipped;
if (n > 0) {
  clipped.assign(samples, samples + n);
  for (float &v : clipped) {
    if (v > 1.0f) v = 1.0f;
    if (v < -1.0f) v = -1.0f;
  }
  samples = clipped.data();
}
// Choose a sane positive sample rate in [8000, 48000].
int32_t sr = static_cast<int32_t>(*FUZZ_PARAM(unsigned int) % 40001) + 8000;
// Call target API
stream->AcceptWaveform(sr, samples, n);
// Validation: We ensure no call after InputFinished, enforce n>=0, sr>0, and
// pass non-null samples only when n>0. stream remains valid and is returned.

// Signal end of input on this stream.
stream->InputFinished();
// Mark attribute so future AcceptWaveform calls on this object can be rejected.
FUZZ_SET_ATTR_INT(stream, "finished", 1);
// Validation: Stream is returned to pool with a "finished" attribute to
// enforce the API rule that AcceptWaveform must not be called afterwards.

// Create a new OnlineStream associated with this recognizer.
sherpa_onnx::cxx::OnlineStream stream_obj = recognizer->CreateStream();
// Move to heap so the fuzzer runtime can manage it across calls.
sherpa_onnx::cxx::OnlineStream *stream = new sherpa_onnx::cxx::OnlineStream(std::move(stream_obj));
// Track the parent recognizer to validate association in other stubs.
FUZZ_SET_ATTR_PTR(stream, "parent", (void*)recognizer);
FUZZ_SET_ATTR_INT(stream, "finished", 0);
// Validation: We return both the recognizer (unchanged) and the new stream.
// Parent linkage is recorded for downstream checks (e.g., IsReady/Decode).

// Ensure the stream belongs to this recognizer using recorded parent linkage.
void *parent = FUZZ_GET_ATTR_PTR(stream, "parent");
if (parent != (void*)recognizer) { FUZZ_BAIL(); }
// Call target function; result is intentionally unused here to exercise path.
(void)recognizer->IsReady(stream);
// Validation: We assert recognizer-stream association via attributes and do not
// mutate ownership; both objects are returned unchanged.

// Validate association
void *parent = FUZZ_GET_ATTR_PTR(stream, "parent");
if (parent != (void*)recognizer) { FUZZ_BAIL(); }
// Enforce precondition: IsReady(stream) must be true before Decode.
if (!recognizer->IsReady(stream)) { FUZZ_BAIL(); }
// Execute one decode step
recognizer->Decode(stream);
// Validation: Preconditions checked, objects preserved, and side-effects are
// limited to the recognizer/stream's internal state.

// Validate association
void *parent = FUZZ_GET_ATTR_PTR(stream, "parent");
if (parent != (void*)recognizer) { FUZZ_BAIL(); }
// Call target function to retrieve the current result
( void )recognizer->GetResult(stream);
// Validation: We don't assert content since it may be empty without prior
