// Validate association
void *parent = FUZZ_GET_ATTR_PTR(stream, "parent");
if (parent != (void*)recognizer) { FUZZ_BAIL(); }
// Reset the stream state
recognizer->Reset(stream);
// Validation: Safe to call on valid association; both objects are returned.

