import random
import string
from typing import List

# We generate UTF-8 free-form text suitable for various fuzz stubs that expect
# natural-language or generic string parameters. Ensure valid UTF-8 and avoid
# runtime formatting errors.

MAX_BYTES = 4096

EMOJIS = [
    "😀", "😅", "🤖", "🎉", "🔥", "✨", "✅", "❌", "💡", "🧪", "🎵", "📦", "📚", "📝"
]

CJK_SNIPPETS = [
    "今天天气很好。",
    "语音转写：你好，世界！",
    "测试模型类型：转导器、CTC、Paraformer。",
]

RTL_SNIPPETS = [
    "مرحبا بالعالم",
    "שלום עולם",
]

COMBINING = "e\u0301 a\u0308 o\u0302 n\u0303"

PUNCT_VARIANTS = [
    ", . ! ? ; : — – ( ) [ ] { } \" ' …",
]

NUMERIC_SNIPPETS = [
    "Numbers: 0 1 2 3 10 42 100 3.14159 -273.15 1e-6",
    "时间戳：00:00.000 -> 01:23.456",
]

LANG_SENTENCES = [
    "This is a test of the automatic speech recognition system.",
    "Hotwords: sherpa, onnx, zipformer, whisper, canary.",
    "Please, punctuate this text properly when models are loaded.",
    "CJK mixed 文本 with ASCII and symbols!",
    "关键词：你好，世界, 开始 结束, 语音 识别。",
    "Punctuation should handle quotes, dashes — and ellipsis… correctly.",
    "ASR decoding method: greedy_search | modified_beam_search | fast_beam_search.",
    "BPE tokens example: ▁the ▁quick ▁brown ▁fox ▁jumps ▁over ▁the ▁lazy ▁dog",
]

# Path-like and JSON-like forms for configs that accept arbitrary strings
PATH_TEMPLATES = [
    "/models/asr/{name}/{ver}/model.onnx",
    "C:/ProgramData/sherpa/{name}/v{ver}/tokens.txt",
    "relative/path/{name}_{ver}.fst",
]

# Use double braces to escape literal braces for str.format
JSON_TEMPLATES = [
    '{{"decoding_method":"{method}","provider":"cpu","model_type":"{model}"}}',
    '{{"hotwords":"{hot}","score":{score:.2f}}}',
]

METHODS = ["greedy_search", "modified_beam_search", "fast_beam_search", "ctc_prefix_beam_search"]
MODELS = ["transducer", "ctc", "paraformer", "whisper", "zipformer", "moonshine", "sense_voice"]

KEYWORD_LISTS = [
    "hey siri, ok google, alexa, cortana",
    "你好 小度, 小爱 同学, 天猫 精灵",
    "start recording, stop recording, mute microphone",
]

def rand_word(rng: random.Random, min_len=3, max_len=12) -> str:
    alphabet = string.ascii_letters + string.digits + "_-"
    n = rng.randint(min_len, max_len)
    return ''.join(rng.choice(alphabet) for _ in range(n))

def make_path(rng: random.Random) -> str:
    tmpl = rng.choice(PATH_TEMPLATES)
    return tmpl.format(name=rand_word(rng), ver=rng.randint(1, 20))

def make_json_like(rng: random.Random) -> str:
    tmpl = rng.choice(JSON_TEMPLATES)
    return tmpl.format(method=rng.choice(METHODS), model=rng.choice(MODELS), hot=rand_word(rng), score=rng.random()*3.0)

def make_bpe_line(rng: random.Random) -> str:
    pieces = ["▁" + rand_word(rng, 2, 8) for _ in range(rng.randint(6, 14))]
    return " ".join(pieces)

def make_keywords(rng: random.Random) -> str:
    if rng.random() < 0.5:
        return rng.choice(KEYWORD_LISTS)
    kws = []
    for _ in range(rng.randint(3, 8)):
        part = rng.choice([rand_word(rng), rng.choice(CJK_SNIPPETS)])
        kws.append(part if len(part) < 24 else part[:24])
    return ", ".join(kws)

def make_sentence_block(rng: random.Random) -> str:
    parts: List[str] = []
    parts.append(rng.choice(LANG_SENTENCES))
    if rng.random() < 0.7:
        parts.append(rng.choice(CJK_SNIPPETS))
    if rng.random() < 0.4:
        parts.append(rng.choice(RTL_SNIPPETS))
    if rng.random() < 0.6:
        parts.append(COMBINING)
    if rng.random() < 0.8:
        parts.append(rng.choice(NUMERIC_SNIPPETS))
    if rng.random() < 0.8:
        parts.append(rng.choice(PUNCT_VARIANTS))
    if rng.random() < 0.7:
        parts.append("Emojis: " + " ".join(rng.sample(EMOJIS, rng.randint(3, min(6, len(EMOJIS))))))
    return "\n".join(parts)

def make_long_word(rng: random.Random) -> str:
    base = rand_word(rng, 16, 64)
    extra = rng.choice(["你好", "मॉडल", "тест", "árvíztűrő"])
    return base + extra + base

def assemble(rng: random.Random) -> str:
    choice = rng.random()
    segments: List[str] = []
    if choice < 0.20:
        segments.append(make_sentence_block(rng))
    elif choice < 0.40:
        segments.append(make_keywords(rng))
        if rng.random() < 0.5:
            segments.append("score=" + f"{rng.uniform(0.5,3.0):.2f}")
    elif choice < 0.55:
        segments.append(make_json_like(rng))
    elif choice < 0.70:
        segments.extend([make_path(rng) for _ in range(rng.randint(1, 3))])
    elif choice < 0.85:
        segments.append(make_bpe_line(rng))
    else:
        segments.append(make_sentence_block(rng))
        segments.append(make_long_word(rng))
    if rng.random() < 0.3:
        segments.append("")
    text = "\n".join(segments)
    encoded = text.encode('utf-8')
    if len(encoded) > MAX_BYTES:
        approx = int(len(text) * (MAX_BYTES / len(encoded)))
        text = text[:max(1, approx)]
        encoded = text.encode('utf-8')[:MAX_BYTES]
        text = encoded.decode('utf-8', errors='ignore')
        encoded = text.encode('utf-8')
    return text


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    text = assemble(rng)
    return text.encode('utf-8')

import io
import os
import random
from typing import List

def _lines_join(lines: List[str]) -> bytes:
    return ("\n".join(lines) + "\n").encode("utf-8")

# We generate a plausible tokens/vocabulary file that covers common formats used by
# sherpa-onnx models: one token per line, with optional score/id columns, and a
# few special tokens. This can be fed to FUZZ_PARAM_FILENAME (written by harness)
# or FUZZ_PARAM_STR (read as inline buffer by some stubs).

def _gen_wordpiece_vocab(rng: random.Random, n: int) -> List[str]:
    # Typical BPE/wordpiece style: with specials and ASCII words/subwords
    specials = ["<unk>", "<blk>", "<s>", "</s>", "<pad>"]
    vocab = specials.copy()
    # include some unicode and punctuation to exercise parsers
    base = [
        "the", "a", "to", "##ing", "##ed", "你", "好", "，", "。", "音", "频",
        "@@@", "[space]", "<bpe>", "▁hello", "▁world",
    ]
    vocab.extend(base)
    while len(vocab) < n:
        choice = rng.randint(0, 4)
        if choice == 0:
            vocab.append("##" + _rand_alpha(rng, rng.randint(2, 6)))
        elif choice == 1:
            vocab.append(_rand_alpha(rng, rng.randint(2, 8)))
        elif choice == 2:
            vocab.append("▁" + _rand_alpha(rng, rng.randint(2, 8)))
        else:
            # Some CJK chars
            vocab.append(chr(rng.randint(0x4e00, 0x9fa5)))
    return vocab[:n]

_def_punct = [",", ".", "?", "!", ";", ":", "…"]

def _rand_alpha(rng: random.Random, n: int) -> str:
    letters = "abcdefghijklmnopqrstuvwxyz"
    return "".join(rng.choice(letters) for _ in range(n))

def _maybe_with_ids_or_scores(rng: random.Random, tokens: List[str]) -> List[str]:
    # Randomly add ID or score columns seen in some vocab formats.
    style = rng.choice(["plain", "id", "score", "id_score"])  # variations
    out = []
    for i, t in enumerate(tokens):
        if style == "plain":
            out.append(t)
        elif style == "id":
            out.append(f"{t} {i}")
        elif style == "score":
            # negative log-prob style
            score = -(rng.random() * 10.0)
            out.append(f"{t} {score:.4f}")
        else:  # id_score
            score = -(rng.random() * 10.0)
            out.append(f"{t} {i} {score:.6f}")
    return out

def _inject_useful_tokens(rng: random.Random, lines: List[str]) -> None:
    # Ensure some special tokens and punctuation exist to pass various checks
    must_haves = ["<blk>", "<unk>", "<s>", "</s>", "<pad>"] + _def_punct
    # If lines carry columns, ensure raw tokens appear at least once as plain
    # Add a small header comment sometimes
    if rng.random() < 0.3:
        lines.insert(0, "# sherpa-onnx tokens file")
    for tok in must_haves:
        if not any(l.split()[0] == tok for l in lines if l and l[0] != '#'):
            lines.insert(rng.randint(0, len(lines)), tok)

def _cap_size(buf: bytes, max_bytes: int = 4096) -> bytes:
    if len(buf) <= max_bytes:
        return buf
    # Try to cut at newline boundary to keep lines intact
    cut = buf[:max_bytes]
    last_nl = cut.rfind(b"\n")
    if last_nl > 0:
        return cut[:last_nl+1]
    return cut

def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Decide vocabulary size and style to cover a range of model expectations.
    vocab_size = rng.randint(50, 800)  # small to mid-size
    tokens = _gen_wordpiece_vocab(rng, vocab_size)

    # Optionally add blank or CTC-specific tokens explicitly
    if rng.random() < 0.7 and "<blk>" not in tokens:
        tokens.insert(0, "<blk>")
    if rng.random() < 0.5 and "<space>" not in tokens:
        tokens.append("<space>")

    lines = _maybe_with_ids_or_scores(rng, tokens)

    # Sometimes append a JSON-like metadata footer some tools tolerate
    if rng.random() < 0.2:
        lines.append("# meta: type=tokens format=plain")

    _inject_useful_tokens(rng, lines)

    buf = _lines_join(lines)
    buf = _cap_size(buf, 4096)
    return buf
